// A4 vector text/tables for quantity reports. No browser or Excel dependency.
static partial class EngineeringQuantityPdf {
 // Body text uses the 7pt minimum to save paper (owner preference, 16 Nov 2026); headings stay larger.
 const double Left=36,Right=559.28,Bottom=50,Line=8.8,Body=7;
 static readonly Encoding Encoding1252=Encoding.GetEncoding(1252);
 static string N(double value){return value.ToString("0.###",CultureInfo.InvariantCulture);}
 static string Clean(string text){return (text??"").Replace("\r","").Replace("Σ","Sum ").Replace("≥",">=").Replace("≤","<=").Replace("→"," to ").Replace("⁴","^4").Replace("³","3").Replace("²","2").Replace("−","-");}
 // The vector PDF uses WinAnsi (Windows-1252) fonts, which have no Greek letters; spell them out instead of printing "?".
 static readonly string[][] Greek={new[]{"δ","d"},new[]{"Δ","Delta"},new[]{"λ","lambda"},new[]{"ξ","xi"},new[]{"ρ","rho"},new[]{"γ","gamma"},new[]{"μ","mu"},new[]{"α","alpha"},new[]{"β","beta"},new[]{"ψ","psi"},new[]{"θ","theta"},new[]{"φ","phi"},new[]{"π","pi"},new[]{"σ","sigma"},new[]{"ε","eps"},new[]{"ω","omega"},new[]{"√","sqrt"},new[]{"∞","inf"},new[]{"′","'"},new[]{"⁴","^4"}};
 internal static string WinAnsi(string text){var b=new System.Text.StringBuilder(Clean(text));foreach(var g in Greek)b.Replace(g[0],g[1]);return b.ToString();}
 static string Escape(string text){return WinAnsi(text).Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)");}
 static double Measure(string text,double size,bool bold){var widths=bold?BoldWidths:RegularWidths;double width=0;foreach(byte c in Encoding1252.GetBytes(WinAnsi(text)))width+=widths[c];return width*size;}
 internal static List<string> Wrap(string text,double width,double size,bool bold=false){var lines=new List<string>();foreach(string paragraph in Clean(text).Split('\n')){string current="";foreach(string word in paragraph.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries)){if(current!=""&&Measure(current+" "+word,size,bold)>width){lines.Add(current);current="";}string remaining=word;while(Measure(remaining,size,bold)>width){int take=1;while(take<remaining.Length&&Measure(remaining.Substring(0,take+1),size,bold)<=width)take++;if(current!=""){lines.Add(current);current="";}lines.Add(remaining.Substring(0,take));remaining=remaining.Substring(take);}if(remaining!="")current=current==""?remaining:current+" "+remaining;}lines.Add(current);}return lines.Count==0?new List<string>{""}:lines;}
 internal sealed class Layout {
  internal const double BodySize=Body;
  public readonly List<StringBuilder> Pages=new List<StringBuilder>();internal readonly List<List<ReportPaintCommand>> DrawingPages=new List<List<ReportPaintCommand>>();List<ReportPaintCommand> drawing;StringBuilder page;double y;EngineeringReport report;bool[] numericColumns;
  public Layout(EngineeringReport report){this.report=report;NewPage();}
  void Text(string text,double x,double top,double size=9,bool bold=false,string color="0.13 0.18 0.23"){drawing.Add(new ReportPaintCommand{Kind="text",Text=Clean(text),X=x,Y=top,Size=size,Bold=bold,Color=color});page.Append("BT /").Append(bold?"F2":"F1").Append(" ").Append(N(size)).Append(" Tf ").Append(color).Append(" rg 1 0 0 1 ").Append(N(x)).Append(" ").Append(N(top)).Append(" Tm (").Append(Escape(text)).Append(") Tj ET\n");}
  void Rule(double top){drawing.Add(new ReportPaintCommand{Kind="rule",Y=top});page.Append("q 0.77 0.81 0.84 RG 0.5 w ").Append(N(Left)).Append(" ").Append(N(top)).Append(" m ").Append(N(Right)).Append(" ").Append(N(top)).Append(" l S Q\n");}
  void Fill(double x,double top,double w,double h,string color){drawing.Add(new ReportPaintCommand{Kind="fill",X=x,Y=top,W=w,H=h,Color=color});page.Append("q ").Append(color).Append(" rg ").Append(N(x)).Append(" ").Append(N(top-h)).Append(" ").Append(N(w)).Append(" ").Append(N(h)).Append(" re f Q\n");}
  void NewPage(){page=new StringBuilder();Pages.Add(page);drawing=new List<ReportPaintCommand>();DrawingPages.Add(drawing);
   foreach(var tile in ReportWatermarkPattern.Active())page.Append("q /WMOpacity gs ").Append(N(tile[2])).Append(" 0 0 ").Append(N(tile[2])).Append(" ").Append(N(tile[0])).Append(" ").Append(N(841.89-tile[1]-tile[2])).Append(" cm /Watermark Do Q\n");
   Text(report.Title.IndexOf("PURLIN",StringComparison.OrdinalIgnoreCase)>=0||report.Title.IndexOf("TRUSS",StringComparison.OrdinalIgnoreCase)>=0?"DTCE  /  ENGINEERING CALCULATION REPORT":"DTCE  /  ENGINEERING QUANTITY REPORT",Left,806,8,true);Text("v"+Engine.Version,Right-Measure("v"+Engine.Version,7,false),806,7);Rule(795);y=775;
   if(Pages.Count==1){Paragraph(report.Title,14,true);if(!string.IsNullOrWhiteSpace(report.Subtitle))Paragraph(report.Subtitle,Body);y-=3;Paragraph("Project: "+(string.IsNullOrWhiteSpace(report.Project)?"Not set":report.Project),8,true);Paragraph("Location: "+(string.IsNullOrWhiteSpace(report.Location)?"Not set":report.Location),Body);if(!string.IsNullOrWhiteSpace(report.Office))Paragraph("Office: "+report.Office,Body);y-=5;Rule(y);y-=12;}
   else {Text(Short(report.Title,95),Left,y,8,true);y-=15;}
  }
  static string Short(string value,int max){return value==null?"":value.Length<=max?value:value.Substring(0,max-1)+"…";}
  void Space(double height){if(y-height<Bottom)NewPage();}
  public void Paragraph(string text,double size=Body,bool bold=false){var lines=Wrap(text,Right-Left,size,bold);foreach(string line in lines){Space(size+4);Text(line,Left,y,size,bold);y-=size*1.25;}y-=3;}
  public void Heading(string title){var lines=Wrap(title,Right-Left-10,9,true);Space(lines.Count*12+36);y-=4;foreach(var line in lines){Text(line,Left,y,9,true,"0.16 0.28 0.39");y-=12;}Rule(y+3);y-=8;}
  // Content-aware column widths: every column gets at least its longest word; spare width goes to columns with longer text.
  double[] Widths(EngineeringReportBlock block){var headers=block.Headers;int n=headers.Length;double total=Right-Left;var minimum=new double[n];var natural=new double[n];
   for(int i=0;i<n;i++){var cells=new[]{headers[i]}.Concat(block.Rows.Select(r=>i<r.Length?r[i]:"")).ToList();
    minimum[i]=cells.SelectMany(c=>Clean(c).Split(new[]{' ','\n'},StringSplitOptions.RemoveEmptyEntries)).Select(w=>Measure(w,Body,true)).DefaultIfEmpty(0).Max()+12;
    natural[i]=Math.Min(total*.7,cells.Select(c=>Clean(c).Split('\n').Select(l=>Measure(l,Body,false)).DefaultIfEmpty(0).Max()).DefaultIfEmpty(0).Max()+12);natural[i]=Math.Max(natural[i],minimum[i]);}
   double minSum=minimum.Sum(),natSum=natural.Sum();var widths=new double[n];
   if(minSum>=total){for(int i=0;i<n;i++)widths[i]=total*minimum[i]/minSum;}
   else if(natSum<=total){for(int i=0;i<n;i++)widths[i]=natural[i]*total/natSum;}
   else{double spare=total-minSum,want=natSum-minSum;for(int i=0;i<n;i++)widths[i]=minimum[i]+spare*(natural[i]-minimum[i])/want;}
   return widths;}
  void Row(List<string>[] lines,double[] widths,int first,int count,bool header,bool shaded){double height=count*Line+6;double x=Left;if(header||shaded)Fill(x,y+4,Right-Left,height,header?"0.9 0.93 0.96":"0.975 0.98 0.985");for(int i=0;i<widths.Length;i++){for(int line=0;line<count;line++){int at=first+line;if(at>=lines[i].Count)continue;string value=lines[i][at];double number;bool numeric=!header&&numericColumns!=null&&numericColumns[i]&&double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out number);Text(value,numeric?x+widths[i]-5-Measure(value,Body,false):x+5,y-6.5-line*Line,Body,header);}x+=widths[i];}y-=height;Rule(y+4);}
  public void Table(EngineeringReportBlock block){if(block.Headers==null||block.Headers.Length==0)return;numericColumns=block.Headers.Select(h=>h.IndexOf("quantity",StringComparison.OrdinalIgnoreCase)>=0||h.IndexOf("amount",StringComparison.OrdinalIgnoreCase)>=0).ToArray();var widths=Widths(block);var header=block.Headers.Select((h,i)=>Wrap(h,widths[i]-10,Body,true)).ToArray();int headerLines=header.Max(l=>l.Count);double headerHeight=headerLines*Line+6;Space(headerHeight+24);Row(header,widths,0,headerLines,true,false);int number=0;foreach(var values in block.Rows){var lines=widths.Select((w,i)=>Wrap(i<values.Length?values[i]:"",w-10,Body)).ToArray();int total=lines.Max(l=>l.Count),offset=0;if(total*Line+6<=680&&y-total*Line-6<Bottom){NewPage();Row(header,widths,0,headerLines,true,false);}while(offset<total){int available=(int)Math.Floor((y-Bottom-6)/Line);if(available<1){NewPage();Row(header,widths,0,headerLines,true,false);continue;}int count=Math.Min(total-offset,available);Row(lines,widths,offset,count,false,number%2==1);offset+=count;if(offset<total){NewPage();Row(header,widths,0,headerLines,true,false);}}number++;}y-=6;}
  public void Finish(){for(int i=0;i<Pages.Count;i++){page=Pages[i];drawing=DrawingPages[i];Rule(39);Text("Generated "+report.Generated.ToString("dd MMM yyyy",CultureInfo.InvariantCulture)+"  ·  SI units as shown  ·  Review copy",Left,25,7);string count="Page "+(i+1)+" / "+Pages.Count;Text(count,Right-Measure(count,7,false),25,7);}}
