 internal static Layout Plan(EngineeringReport report){var layout=new Layout(report);int number=0;foreach(var section in report.Sections){if(section.Records.Count==0)continue;layout.Heading((++number).ToString("00")+"  "+section.Title);foreach(var block in section.Records)if(block.Kind=="table")layout.Table(block);else layout.Paragraph(block.Text,Layout.BodySize);}layout.Finish();return layout;}
 public static void Write(string path,EngineeringReport report){WritePages(path,Plan(report).Pages);}
 static byte[] Stream(byte[] bytes,string dictionary=""){return Encoding1252.GetBytes("<< "+dictionary+" /Length "+bytes.Length+" >>\nstream\n").Concat(bytes).Concat(Encoding1252.GetBytes("\nendstream")).ToArray();}
 static void WritePages(string path,List<StringBuilder> pages){var security=new PdfSecurity();var objects=new List<byte[]>();Action<string> add=value=>objects.Add(Encoding1252.GetBytes(value));add("<< /Type /Catalog /Pages 2 0 R >>");add("<< /Type /Pages /Count "+pages.Count+" /Kids ["+string.Join(" ",Enumerable.Range(0,pages.Count).Select(i=>(7+2*i)+" 0 R"))+"] >>");add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");objects.Add(Stream(security.Encrypt(ReportWatermarkAssets.Jpeg,5),"/Type /XObject /Subtype /Image /Width "+ReportWatermarkAssets.Width+" /Height "+ReportWatermarkAssets.Height+" /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode"));add("<< /Type /ExtGState /ca 0.18 /CA 0.18 >>");for(int i=0;i<pages.Count;i++){int content=8+i*2;add("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Watermark 5 0 R >> /ExtGState << /WMOpacity 6 0 R >> >> /Contents "+content+" 0 R >>");objects.Add(Stream(security.Encrypt(Encoding1252.GetBytes(pages[i].ToString()),content)));}int encryption=objects.Count+1;add(security.Dictionary());string full=Path.GetFullPath(path),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){Action<string> put=text=>{var bytes=Encoding1252.GetBytes(text);output.Write(bytes,0,bytes.Length);};put("%PDF-1.6\n");var offsets=new List<long>{0};for(int i=0;i<objects.Count;i++){offsets.Add(output.Position);put((i+1)+" 0 obj\n");output.Write(objects[i],0,objects[i].Length);put("\nendobj\n");}long xref=output.Position;put("xref\n0 "+offsets.Count+"\n0000000000 65535 f \n");foreach(var offset in offsets.Skip(1))put(offset.ToString("D10",CultureInfo.InvariantCulture)+" 00000 n \n");put("trailer\n<< /Size "+offsets.Count+" /Root 1 0 R /Encrypt "+encryption+" 0 R /ID [<"+PdfSecu